ValidationRule.errorConditionFormula:
AND(
    /* 項目が空白でない場合のみチェックを行う */
    NOT(ISBLANK( SellADContract_URL__c )),

    /* 以下の「許可する条件」のいずれにも当てはまらない(NOT)場合にエラーとする */
    NOT(
        OR(
            /* パターン1: google.com と usp=sharing の両方を含む */
            AND(
                CONTAINS( SellADContract_URL__c , "google.com"),
                CONTAINS( SellADContract_URL__c , "usp=sharing")
            ),
            /* パターン2: box.com/s/ を含む */
            CONTAINS( SellADContract_URL__c , "box.com/s/")
        )
    )
)
